<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigWebauthnRpIdAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWebauthnRpIdAccessor trait.
 *
 * Covers null default, string/VO assignment via withWebauthnRpId,
 * getWebauthnRpId/webauthnRpId accessors, and isWebauthnRpIdChanged with/without original.
 */
class TenantConfigWebauthnRpIdAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWebauthnRpId creates a new instance with the WebauthnRpId set
     * from a string value, and getWebauthnRpId returns the primitive string.
     */
    public function testWithWebauthnRpIdFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnRpIdAccessorUnitTest();

        // Act
        $result = $holder->withWebauthnRpId('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getWebauthnRpId());
    }
    /**
     * Asserts that withwebauthnRpId has access to the value object
     * from a string value, and getWebauthnRpId returns the primitive string.
     */
    public function testWithWebauthnRpIdFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnRpIdAccessorUnitTest();

        // Act
        $result = $holder->withWebauthnRpId('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->webauthnRpId()->value());
    }
    public function testChangedWebauthnRpId(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnRpIdAccessorUnitTest();
        $original = $holder->withWebauthnRpId('one');
        $same = $holder->withWebauthnRpId('one');
        $modified = $holder->withWebauthnRpId('other');

        // Act
        $unchanged = $holder->isWebauthnRpIdChanged();
        $withSame = $original->isWebauthnRpIdChanged($same);
        $withDiferent = $original->isWebauthnRpIdChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigWebauthnRpIdAccessorUnitTest
{
    use TenantConfigWebauthnRpIdAccessor;
}
